export default {"documents":{"terms":{"title":"सेवा की शर्तें","description":"आपके और Veyrnox Ltd के बीच अनुबंध — स्वीकार्य उपयोग, क्रेडिट, जनित आउटपुट का लाइसेंस और दायित्व।","b001":"ये शर्तें Veyrnox.ai के आपके उपयोग पर लागू होती हैं, जिसका संचालन {name} करती है; यह {jurisdiction} में पंजीकृत कंपनी है (कंपनी संख्या {companyNo}), जिसका पंजीकृत कार्यालय {office} है। खाता बनाकर या सामग्री जनरेट करके आप इन्हें स्वीकार करते हैं।","b002":"1. सेवा","b003":"Veyrnox.ai तृतीय-पक्ष AI मॉडल से चित्र, वीडियो और ऑडियो बनाने के लिए क्रेडिट-आधारित सेवा है। प्रत्येक जनरेशन पुष्टि से पहले अपनी क्रेडिट लागत दिखाता है। हम कभी भी मॉडल जोड़ सकते हैं, हटा सकते हैं या उनकी कीमत बदल सकते हैं; जनरेशन के समय दिखाई गई कीमत ही आप चुकाते हैं।","b004":"2. खाते","b005":"आपकी आयु 18 वर्ष या अधिक होनी चाहिए, या आपने अपने निवास स्थान की वयस्कता की आयु प्राप्त की हो।","b006":"अपनी लॉगिन जानकारी सुरक्षित रखें। आपके खाते की गतिविधि के लिए आप ज़िम्मेदार हैं।","b007":"प्रति व्यक्ति एक खाता। निःशुल्क क्रेडिट अनुदान का दुरुपयोग करने वाले खाते निलंबित किए जा सकते हैं।","b008":"3. क्रेडिट","b009":"नए खातों को 10 निःशुल्क क्रेडिट मिलते हैं। इनका नकद मूल्य नहीं होता, इन्हें निकाला नहीं जा सकता, ये खरीदे गए क्रेडिट से पहले उपयोग होते हैं और उपयोग न होने पर दिए जाने के 90 दिन बाद समाप्त हो जाते हैं।","b010":"खरीदे गए क्रेडिट कभी समाप्त नहीं होते।","b012":"धनवापसी नीति","b011":"जनरेशन प्रस्तुत करने पर खरीदे गए क्रेडिट काटे जाते हैं। यदि प्रदाता जनरेशन पूरा नहीं करता, तो कटौती स्वचालित रूप से आपके शेष में लौट जाती है। हमारी {inline1} देखें।","b013":"क्रेडिट खातों के बीच हस्तांतरित नहीं किए जा सकते।","b014":"रेफ़रल पुरस्कार: यदि मित्र आपके रेफ़रल लिंक से जुड़कर पहला क्रेडिट पैक खरीदता है, तो आप उस पैक के 10% मूल्य के क्रेडिट कमा सकते हैं। खरीद की धनवापसी या विवाद न होने पर वे खरीद के 14 दिन बाद आपके शेष में जुड़ते हैं। रेफ़रल क्रेडिट का नकद मूल्य नहीं है, वे कभी समाप्त नहीं होते और कभी धन के रूप में नहीं दिए जाते। पुरस्कार जुड़ने के बाद खरीद की धनवापसी या विवाद होने पर, आपके पास बचे खरीदे गए क्रेडिट की सीमा तक पुरस्कार वापस लिया जाता है। पुरस्कार प्रति कैलेंडर माह 20 और 2,000 क्रेडिट तक सीमित हैं; स्वयं को रेफ़र करने या दुरुपयोग पर हम पुरस्कार रोक या वापस ले सकते हैं।","b015":"क्रेडिट पैक Stripe Checkout से बेचे जाते हैं। Stripe Managed Payments के अंतर्गत Stripe, Inc. आपकी क्रेडिट पैक खरीद का Merchant of Record और अभिलेखित विक्रेता है: Stripe भुगतान लेता है, आपके स्थान पर लागू VAT या बिक्री कर वसूलकर जमा करता है और रसीद जारी करता है। कर सहित कुल राशि भुगतान से पहले दिखाई जाती है। Veyrnox Ltd वह Veyrnox.ai सेवा देता है जिस पर क्रेडिट खर्च होते हैं, और ये शर्तें उसके उपयोग पर लागू होती हैं। Stripe कार्ड विवरण संभालता है; हम उसे कभी नहीं देखते।","b017":"धनवापसी नीति","b016":"I want my credits added to my account straight away. I understand that once I use any of these credits to generate, I lose my right to cancel this purchase. खरीदने से पहले आपको ऊपर दिए गए कथन की पुष्टि करने वाला बॉक्स चुनना होगा। अंग्रेज़ी कथन प्रभावी है। हमारी {inline1} देखें।","b018":"3A. क्रेडिट सदस्यताएँ","b019":"Credit Subscription सदस्यता लेते समय दिखाई गई सदस्यता क्रेडिट की संख्या देता है और प्रदर्शित मासिक USD कीमत तथा चेकआउट पर दिखाया गया कर लेता है। रद्द करने तक यह हर महीने स्वचालित रूप से नवीनीकृत होता है।","b020":"सदस्यता क्रेडिट प्रत्येक आवर्ती भुगतान की पुष्टि के बाद ही जोड़े जाते हैं। वे निःशुल्क क्रेडिट और Credit Pack क्रेडिट से पहले उपयोग होते हैं, भुगतान किए गए चक्र के अंत में समाप्त होते हैं और अगले चक्र में नहीं जुड़ते। नवीनीकरण रद्द करने से उनकी समाप्ति नहीं बढ़ती।","b022":"क्रेडिट और बिलिंग","b021":"आप {inline1} से कभी भी नवीनीकरण रोक सकते हैं। अगले चक्र का शुल्क नहीं लिया जाएगा और वर्तमान भुगतान चक्र दिखाई गई समाप्ति तारीख तक जारी रहेगा।","b023":"प्रारंभिक भुगतान चक्र के लिए 14 दिनों के भीतर विचार-अवधि की पूरी धनवापसी तभी माँग सकते हैं जब उस चक्र का कोई सदस्यता क्रेडिट उपयोग न हुआ हो। कोई क्रेडिट उपयोग हो चुका हो तब भी अगला नवीनीकरण रोक सकते हैं। सर्वर पात्रता जाँचता है और पुष्टि तक धनवापसी की स्थिति पूर्ण नहीं होती।","b024":"चेकआउट से पहले आपको आवर्ती कीमत और अंतराल, प्रत्येक पुष्ट भुगतान के बाद मिलने वाले क्रेडिट की संख्या तथा बिना आगे जुड़ने वाली समाप्ति को स्पष्ट रूप से स्वीकार करना होगा। कर सहित अंतिम कीमत भुगतान से पहले दिखाई जाती है।","b025":"3B. Veyrnox.ai Publish Plan","b026":"Veyrnox.ai Publish Plan योजना पृष्ठ पर दिखाई गई उन्नत प्रकाशन, विश्लेषण और खाता सुविधाएँ देता है। यह चेकआउट से पहले चुनी गई साप्ताहिक, मासिक या वार्षिक USD कीमत और चेकआउट पर दिखाया गया कर लेता है तथा रद्द करने तक उसी अंतराल पर स्वचालित रूप से नवीनीकृत होता है।","b027":"आप Publish Plan पृष्ठ या उसके Stripe बिलिंग पोर्टल से नवीनीकरण रोक सकते हैं। अगले चक्र का शुल्क नहीं लिया जाएगा और भुगतान वाली सुविधाएँ प्रदर्शित भुगतान अवधि के अंत तक चलती रहेंगी।","b028":"चेकआउट से पहले आपको आवर्ती कीमत और अंतराल स्पष्ट रूप से स्वीकार करना होगा। कर सहित अंतिम कीमत भुगतान से पहले दिखाई जाती है।","b029":"4. आपके इनपुट और आउटपुट","b030":"अपलोड किए गए प्रॉम्प्ट और संदर्भ फ़ाइलों में आपके जो अधिकार हैं, वे आपके पास रहते हैं। आप हमें केवल सेवा चलाने के लिए उन्हें संसाधित करने का लाइसेंस देते हैं।","b031":"इन शर्तों और प्रत्येक अंतर्निहित मॉडल प्रदाता के लाइसेंस के अधीन, आप जनित आउटपुट का व्यक्तिगत और व्यावसायिक उपयोग कर सकते हैं।","b032":"आउटपुट AI-जनित हैं। वर्तमान में हम जनित फ़ाइलों के साथ सामग्री प्रमाणपत्र या मशीन-पठनीय उत्पत्ति हस्ताक्षर नहीं जोड़ते। आउटपुट प्रकाशित करने पर प्लेटफ़ॉर्म या लागू कानून द्वारा आवश्यक लेबल लगाने की ज़िम्मेदारी आपकी है। यदि हम प्रमाणपत्र जोड़ना शुरू करें, तो यहाँ बताएँगे; उसके बाद आप उन्हें हटा या बदल नहीं सकते।","b033":"सेवा का उपयोग स्पष्ट यौन, गैरकानूनी या दूसरों के अधिकारों का उल्लंघन करने वाली सामग्री, नाबालिगों से संबंधित यौनकृत सामग्री, बिना सहमति की अंतरंग छवियाँ, यौन डीपफ़ेक, मैलवेयर या हानिकारक धोखे के उद्देश्य वाली सामग्री बनाने, अपलोड करने या प्रकाशित करने के लिए नहीं किया जा सकता।","b034":"5. स्वीकार्य उपयोग","b035":"लिखित समझौते के बिना स्क्रैपिंग, रिवर्स इंजीनियरिंग, अनुरोध-दर सीमा से बचना या पहुँच दोबारा बेचना निषिद्ध है। सेवा या अन्य उपयोगकर्ताओं को जोखिम में डालने वाले खातों को हम सीमित या निलंबित कर सकते हैं।","b036":"6. उपलब्धता","b037":"सेवा तृतीय-पक्ष मॉडल प्रदाताओं पर निर्भर है और बाधित हो सकती है। हम निर्बाध पहुँच का वादा नहीं करते। विफल जनरेशन की वापसी होती है; डाउनटाइम के लिए और कुछ देय नहीं है।","b038":"7. एम्बेड किया गया वीडियो","b040":"YouTube सेवा की शर्तें","b039":"कुछ निःशुल्क Social Cinema श्रृंखलाएँ आधिकारिक YouTube एम्बेडेड प्लेयर से चलती हैं। उन वीडियो का स्रोत YouTube ही रहता है और प्लेयर के उपयोग पर {inline1} भी लागू होती हैं। यदि रचनाकार एम्बेडिंग बंद करे या मूल वीडियो हटा दे तो हम एम्बेड किए गए शीर्षक को हटा सकते हैं।","b041":"7A. Social Cinema प्रकाशन","b043":"Cinema सामग्री नीति","b042":"अनुमोदित रचनाकारों को {inline1} का पालन करना, सटीक Veyrnox दर्शक लेबल चुनना, प्रासंगिक सामग्री चेतावनियाँ घोषित करना और केवल वे फ़ाइलें प्रस्तुत करना आवश्यक है जिन्हें वे उचित रूप से सुरक्षित मानते हों। Veyrnox लेबल मार्गदर्शन हैं, आधिकारिक BBFC वर्गीकरण नहीं। प्रस्तुति प्रकाशन की गारंटी नहीं है।","b044":"हम मेटाडेटा, चित्र, चुने हुए वीडियो फ़्रेम, वाणी या कैप्शन और फ़ाइल-सुरक्षा संकेतों की स्वचालित जाँच कर सकते हैं; प्रस्तुति अलग रख सकते हैं; मानवीय समीक्षा माँग सकते हैं; या शीर्षक अस्वीकार, सीमित, निलंबित या हटा सकते हैं। प्रकाशन से पहले आवश्यक सुरक्षा जाँच उत्तीर्ण होनी चाहिए। रचनाकार Cinema सामग्री नीति में दिए संपर्क माध्यम से निर्णय की अपील कर सकते हैं।","b045":"7B. Cinema Pass","b046":"Cinema Pass सक्रिय रहने पर प्रकाशित Social Cinema फ़िल्मों और एपिसोड तक पहुँच देता है, जो खरीद से पहले दिखाई गई वितरित मिनटों की सीमा के अधीन है। यह कोई क्रेडिट नहीं जोड़ता।","b047":"Pass सदस्यता लेते समय प्रदर्शित आवर्ती USD कीमत और चेकआउट पर दिखाया गया कर लेता है तथा चुने गए विकल्प के अनुसार हर सप्ताह या महीने, रद्द करने तक, स्वचालित रूप से नवीनीकृत होता है।","b048":"आप Cinema Pass पृष्ठ या उसके Stripe बिलिंग पोर्टल से रद्द कर सकते हैं। प्रारंभिक विचार-अवधि के बाहर रद्दीकरण अगला नवीनीकरण रोकता है और पहुँच प्रदर्शित भुगतान अवधि के अंत तक रहती है।","b049":"पहले शुल्क के 14 दिनों के भीतर रद्द करने पर Pass तुरंत समाप्त होता है और वर्तमान भुगतान अवधि के अप्रयुक्त हिस्से की राशि मूल भुगतान विधि पर लौटती है। पृष्ठ बताता है कि यह विकल्प कब उपलब्ध है और पुष्टि तक धनवापसी पूर्ण नहीं होती।","b050":"चेकआउट से पहले आपको Pass तुरंत शुरू करने का स्पष्ट अनुरोध करना होगा और उसके स्वचालित नवीनीकरण तथा विचार-अवधि की व्यवस्था को स्वीकार करना होगा।","b051":"8. दायित्व","b052":"इन शर्तों में ऐसा कुछ नहीं है जो कानून द्वारा असीमित रखे गए दायित्व को सीमित करे। अन्यथा, किसी भी 12 माह की अवधि में आपके प्रति हमारा कुल दायित्व उसी अवधि में आपके द्वारा हमें दी गई राशि तक सीमित है। अप्रत्यक्ष या परिणामी हानि के लिए हम उत्तरदायी नहीं हैं।","b053":"9. उपभोक्ता","b054":"यदि आप UK या EU के उपभोक्ता हैं, तो इन शर्तों से आपके वैधानिक अधिकार प्रभावित नहीं होते।","b055":"10. परिवर्तन और समाप्ति","b056":"हम इन शर्तों को अद्यतन कर सकते हैं; महत्वपूर्ण बदलाव प्रभावी होने से कम से कम 14 दिन पहले साइट पर घोषित होंगे। आप कभी भी खाता बंद कर सकते हैं। उल्लंघन पर हम जहाँ व्यावहारिक हो सूचना देकर अनुबंध समाप्त कर सकते हैं।","b057":"11. कानून","b058":"इन शर्तों पर इंग्लैंड और वेल्स के कानून लागू होते हैं। उपभोक्ता अपने देश के अनिवार्य संरक्षणों का भी सहारा ले सकते हैं।","b059":"संपर्क","b061":"{email}","b060":"{inline1}"},"privacy":{"title":"गोपनीयता नीति","description":"Veyrnox.ai कौन-सा व्यक्तिगत डेटा संसाधित करता है, क्यों, कहाँ रखता है और कितने समय तक रखता है।","b002":"{privacyEmail}","b001":"{name} (“हम”) Veyrnox.ai से संसाधित व्यक्तिगत डेटा का नियंत्रक है। पंजीकृत कार्यालय: {office}। संपर्क: {inline1}।","b003":"हम क्या एकत्र करते हैं","b005":"खाता डेटा","b004":"{inline1} — ईमेल पता, प्रमाणीकरण पहचानकर्ता और Apple या Google से लॉगिन करने पर उनके द्वारा साझा किया गया पहचानकर्ता।","b007":"उपयोग डेटा","b006":"{inline1} — आपके प्रस्तुत प्रॉम्प्ट, चैट संदेश और संदर्भ फ़ाइलें या चित्र, अनुरोधित जनरेशन और चैट उत्तर, क्रेडिट शेष और लेजर इतिहास तथा कार्य की स्थिति।","b009":"Publish डेटा","b008":"{inline1} — चुने गए खातों पर प्रकाशित करने के लिए आवश्यक जुड़े सामाजिक खाते का विवरण, अपलोड किए गए मीडिया, कैप्शन, समय-सारणी और पोस्ट विश्लेषण।","b011":"तकनीकी डेटा","b010":"{inline1} — सेवा सुरक्षित रखने के लिए आवश्यक IP पता, ब्राउज़र और डिवाइस की जानकारी तथा अनुरोध लॉग।","b013":"वैकल्पिक उत्पाद विश्लेषण","b012":"{inline1} — आपकी सहमति पर पृष्ठ पथ, बटन और फ़ॉर्म से इंटरैक्शन, वेब प्रदर्शन माप और तकनीकी त्रुटि विवरण। हम URL क्वेरी स्ट्रिंग, प्रॉम्प्ट, चैट पाठ, फ़ॉर्म मान, अपलोड या जनित मीडिया, पासवर्ड या भुगतान विवरण नहीं भेजते।","b015":"वैकल्पिक सत्र रीप्ले","b014":"{inline1} — अलग सहमति पर पात्र ब्राउज़र सत्रों के अधिकतम 100% का गोपनीयता-मास्क किया हुआ पुनर्निर्माण। सभी पाठ और इनपुट छिपाए जाते हैं; चित्र, वीडियो, ऑडियो, canvas और iframe रोके जाते हैं; कंसोल आउटपुट, अनुरोध या उत्तर के मुख्य भाग और हेडर रिकॉर्ड नहीं होते; लॉगिन, खाता, प्रशासन और भुगतान पृष्ठों पर रीप्ले बंद रहता है।","b017":"भुगतान डेटा","b016":"{inline1} — क्रेडिट पैक Stripe Managed Payments से बेचे जाते हैं, जिसमें Stripe, Inc. Merchant of Record और अभिलेखित विक्रेता है तथा VAT या बिक्री कर वसूलकर जमा करता है। Stripe अपनी गोपनीयता नीति के तहत स्वतंत्र नियंत्रक के रूप में भुगतान विवरण, बिलिंग पता और कर जानकारी लेता है। खाते में क्रेडिट जोड़ने के लिए हमें भुगतान संदर्भ, राशि, मुद्रा, देश और ईमेल मिलते हैं। हम पूरी कार्ड संख्या कभी नहीं देखते या रखते।","b018":"संसाधन का उद्देश्य","b019":"सेवा चलाना और आपके जनरेशन पूरे करना (अनुबंध का निष्पादन)।","b020":"सटीक क्रेडिट लेजर रखना और दुरुपयोग रोकना (वैध हित)।","b021":"कर और सामग्री की उत्पत्ति की आवश्यकताओं सहित कानूनी दायित्व पूरे करना।","b022":"सेवा संदेश भेजना। हम बिना सहमति मार्केटिंग ईमेल नहीं भेजते।","b023":"आपकी सहमति से उत्पाद उपयोग समझना, प्रदर्शन मापना और त्रुटियों तथा काम न करने वाले इंटरैक्शन का निदान करना।","b024":"आपका डेटा कहाँ रहता है","b025":"डेटाबेस और प्रमाणीकरण के लिए Supabase तथा एज होस्टिंग और ऑब्जेक्ट स्टोरेज के लिए Cloudflare का उपयोग करते हैं। खाता डेटा, क्रेडिट लेजर, जनरेशन मेटाडेटा और चैट वार्तालाप यूरोपीय संघ (फ़्रैंकफ़र्ट, जर्मनी) में स्थित Supabase डेटाबेस में रहते हैं। जनित मीडिया यूरोपीय संघ में EU क्षेत्राधिकार प्रतिबंध वाले Cloudflare R2 में रखा जाता है। वैकल्पिक विश्लेषण की सहमति देने पर विश्लेषण, मास्क किए गए रीप्ले और त्रुटि घटनाएँ PostHog Cloud EU में संसाधित होती हैं। आपके प्रॉम्प्ट, चैट संदेश और संदर्भ फ़ाइलें या चित्र केवल आउटपुट बनाने के लिए हमारे मॉडल गेटवे से चुना हुआ मॉडल चलाने वाले तृतीय-पक्ष प्रदाता को भेजे जाते हैं। चैट के लिए हम गेटवे से केवल ऐसे प्रदाता उपयोग करने को कहते हैं जो सामग्री न रखें और उसे मॉडल प्रशिक्षण में न लगाएँ। वेब खोज चालू करने पर प्रश्न खोज प्रदाता को भी भेजा जाता है। हमारी अपनी खोज के माध्यम से चलने पर सेवा विन्यास के अनुसार प्रदाता Exa (exa.ai) या Parallel (parallel.ai) होता है। उसे आपका प्रश्न खोज क्वेरी के रूप में मिलता है; Parallel को चैट वार्तालाप पहचानकर्ता और चुने हुए मॉडल का पहचानकर्ता भी मिलता है। मिले पृष्ठों का पाठ प्रश्न के साथ गेटवे से मॉडल प्रदाता को भेजा जाता है ताकि उत्तर स्रोत उद्धृत कर सके।","b026":"आपका व्यक्तिगत डेटा संसाधित करने वाली कुछ कंपनियाँ यूनाइटेड किंगडम और EEA के बाहर हैं: एज होस्टिंग, मॉडल प्रदाता और Stripe, Inc. (संयुक्त राज्य अमेरिका), जो क्रेडिट पैक खरीद का Merchant of Record है। UK या EEA के बाहर संसाधन होने पर हम संबंधित कंपनी के साथ UK International Data Transfer Agreement या EU Standard Contractual Clauses पर निर्भर करते हैं। डेटाबेस दूसरे क्षेत्र में ले जाने पर स्थानांतरण प्रभावी होने से पहले यह पृष्ठ अद्यतन करेंगे।","b027":"Veyrnox.ai Publish में YouTube डेटा","b029":"Google गोपनीयता नीति","b028":"Social Cinema चुनी गई निःशुल्क श्रृंखलाओं के लिए YouTube का गोपनीयता-वर्धित एम्बेडेड प्लेयर उपयोग करता है। प्ले दबाने से पहले YouTube को थंबनेल, शीर्षक, चलाने की उपलब्धता और सामग्री प्रतिबंध दिखाने हेतु तकनीकी जानकारी मिलती है। वीडियो चलाने पर उसे प्लेबैक और डिवाइस डेटा मिलता है और वह {inline1} के अनुसार कुकी सेट या पढ़ सकता है। हम एम्बेडेड वीडियो की प्रति डाउनलोड या संग्रहित नहीं करते।","b030":"YouTube चैनल को Veyrnox.ai Publish से जोड़ने पर हम Google से चैनल पहचानने, समर्थित चैनल और वीडियो आँकड़े पढ़ने और चुने हुए वीडियो अपलोड करने की अनुमति माँगते हैं। यह सहमति Google लॉगिन से अलग है। पढ़ने की पहुँच जुड़े चैनल और बुनियादी पोस्ट विश्लेषण दिखाने के लिए है। अपलोड पहुँच केवल अभी पोस्ट करने या पोस्ट निर्धारित करने के आपके निर्देशों के पालन में उपयोग होती है।","b031":"जुड़े चैनल का विवरण, अनुमतियाँ, पोस्ट इतिहास और विश्लेषण Supabase में रखते हैं। एक्सेस और रिफ़्रेश टोकन रखने से पहले एन्क्रिप्ट होते हैं और सर्वर निर्धारित अपलोड सहित अधिकृत YouTube API कॉल में उनका उपयोग करता है। लाइब्रेरी का वीडियो चुनने मात्र से वह YouTube पर अपलोड नहीं होता। पोस्ट या शेड्यूल करने पर चुना वीडियो, शीर्षक और विवरण YouTube को भेजते हैं।","b032":"चैनल अलग करने से उसके संग्रहित एक्सेस और रिफ़्रेश टोकन हटते हैं और उस कनेक्शन के लिए आगे का प्रकाशन तथा विश्लेषण संग्रह रुकता है। YouTube पर पहले अपलोड वीडियो नहीं हटते। खाता विवरण, पोस्ट इतिहास और पूर्व विश्लेषण Veyrnox खाते में रहते हैं; नीचे की संपर्क और डेटा-अधिकार प्रक्रिया से उन्हें हटाने का अनुरोध कर सकते हैं। Google खाते से Veyrnox.ai Publish की पहुँच भी रद्द कर सकते हैं।","b034":"Google API Services User Data Policy","b033":"YouTube API से मिले डेटा का उपयोग AI मॉडल प्रशिक्षण या विज्ञापन लक्ष्यीकरण में नहीं करते। Google API से मिली जानकारी का Veyrnox.ai Publish द्वारा उपयोग और हस्तांतरण {inline1}, उसके Limited Use नियमों सहित, का पालन करता है।","b035":"डेटा की सुरक्षा","b036":"YouTube API से प्राप्त संवेदनशील Google उपयोगकर्ता डेटा सहित व्यक्तिगत डेटा को अनधिकृत पहुँच और प्रकटीकरण से बचाने के लिए निम्न सुरक्षा उपाय उपयोग करते हैं:","b038":"परिवहन के दौरान एन्क्रिप्शन","b037":"{inline1} — आपके ब्राउज़र और Veyrnox.ai तथा हमारे सर्वर, Google API और डेटाबेस के बीच भेजे डेटा को HTTPS/TLS से एन्क्रिप्ट करते हैं।","b040":"संग्रहित OAuth टोकन की सुरक्षा","b039":"{inline1} — YouTube एक्सेस और रिफ़्रेश टोकन डेटाबेस में रखने से पहले AES-256-GCM से एन्क्रिप्ट होते हैं। एन्क्रिप्शन कुंजी अलग सर्वर-पक्ष सीक्रेट में रहती है। सर्वर टोकन का उपयोग आपके अधिकृत फ़ीचर के लिए करते हैं और जुड़े खाते के उत्तरों में उन्हें ब्राउज़र को वापस नहीं भेजते।","b042":"पहुँच नियंत्रण","b041":"{inline1} — API आपकी लॉगिन पहचान जाँचते हैं और सुनिश्चित करते हैं कि जुड़े खाते और डेटा आपके हैं। जुड़े खाते और विश्लेषण तालिकाएँ डेटाबेस की पंक्ति-स्तरीय सुरक्षा उपयोग करती हैं; पहुँच नियंत्रित सर्वर कार्यों से होती है, सीधे ब्राउज़र से नहीं।","b043":"प्रस्तावित मॉडल संसाधक: BytePlus","b044":"BytePlus Pte. Ltd. (सिंगापुर) चुने हुए Seedance वीडियो मॉडल का प्रस्तावित संसाधक है। ये मॉडल अभी Veyrnox.ai पर उपलब्ध नहीं हैं। सक्षम होने के बाद ऐसा मॉडल चुनने पर प्रॉम्प्ट और संदर्भ चित्र वीडियो बनाने के लिए सिंगापुर के BytePlus ModelArk को भेजे जाएँगे। यह संसाधन UK और EEA के बाहर होता है; तैयार वीडियो EU स्टोरेज में रखने से जनरेशन संसाधन उन क्षेत्रों के भीतर नहीं हो जाता।","b045":"लागू डेटा-संसाधन और अंतरराष्ट्रीय हस्तांतरण व्यवस्थाएँ स्थापित होने के बाद ही ये मॉडल सक्षम करेंगे। उपलब्ध होने पर सूचना अद्यतन करेंगे।","b046":"प्रतिधारण","b047":"जनित मीडिया 90 दिनों तक रखा जाता है, फिर अपने आप हटता है।","b048":"पूर्ण Publish अपलोड हटाए जाने तक आपके Publish अपलोड में रहते हैं। ड्राफ़्ट, निर्धारित या चल रही पोस्ट में उपयोग फ़ाइल उस पोस्ट के पूरा या रद्द होने तक नहीं हट सकती; उसका मेटाडेटा पोस्ट इतिहास में रहता है। छोड़ दिए गए अपलोड 24 घंटे बाद हटते हैं। अप्रयुक्त फ़ाइल हटाने पर उसके अपलोड लिंक की अवधि समाप्त होने के बाद स्टोरेज से हटाने का कार्य कतार में लगता है, सामान्यतः 20 मिनट के भीतर।","b049":"चैट वार्तालाप तब तक रहते हैं जब तक आप उन्हें हटाते नहीं। चैट हटाने से वह और उसके संदेश तुरंत डेटाबेस से हट जाते हैं।","b050":"डेटाबेस का प्रतिदिन बैकअप होता है और प्रत्येक बैकअप लगभग सात दिन रहता है; इसलिए हटाई गई चैट बैकअप समाप्त होने तक अधिकतम उतने समय उसमें रह सकती है।","b051":"चैट में अपलोड चित्र केवल उत्तर देने तक आवश्यक समय के लिए रखे जाते हैं और 24 घंटे के भीतर हटते हैं। लाइब्रेरी से चैट के लिए चुना चित्र लाइब्रेरी में रहता है और उत्तर देने हेतु मॉडल प्रदाता को भेजा जाता है। वीडियो चुनने पर ब्राउज़र कुछ स्थिर फ़्रेम निकालकर चित्रों के रूप में जोड़ता है; वीडियो स्वयं अपलोड नहीं होता।","b052":"लेजर रिकॉर्ड खाते के अस्तित्व तक और उसके बाद कर कानून द्वारा आवश्यक अवधि तक रहते हैं। क्रेडिट इतिहास में चैट उत्तर की प्रविष्टि मॉडल, विकल्प और लिए गए क्रेडिट दर्ज करती है; उसमें संदेशों का पाठ कभी नहीं होता।","b053":"अनुरोध लॉग थोड़ी सुरक्षा अवधि तक रखे जाते हैं, फिर हटा दिए जाते हैं।","b054":"वैकल्पिक उत्पाद विश्लेषण और त्रुटि घटनाएँ अधिकतम 12 माह रखी जाती हैं। वैकल्पिक सत्र रीप्ले अधिकतम 30 दिन रहते हैं। सहमति वापस लेने पर नया संग्रह रुकता है; खाते से जुड़ी मौजूदा घटनाएँ हटाने का अनुरोध भी कर सकते हैं।","b055":"खाता हटाना","b056":"खाता और सुरक्षा से स्वयं खाता हटा सकते हैं। ऐसा करने पर हर जगह लॉगआउट हो जाते हैं और लॉगिन, चैट, व्यक्तित्व और फ़ोल्डर, जनित फ़ाइलें और उनके प्रॉम्प्ट, Publish कनेक्शन और संग्रहित एक्सेस टोकन तथा रेफ़रल कोड मिट जाते हैं। अप्रयुक्त क्रेडिट जब्त होते हैं और धनवापसी नहीं होती; पुष्टि से पहले स्क्रीन उनकी संख्या बताती है। खुला भुगतान विवाद या सामग्री रोक, सक्रिय सदस्यता अथवा चल रहे जनरेशन के दौरान खाता नहीं हटा सकते; स्क्रीन संबंधित कारण दिखाती है।","b057":"कुछ रिकॉर्ड हटाने के बाद नाम और ईमेल के बिना रहते हैं: कर कानून की अवधि तक क्रेडिट और भुगतान रिकॉर्ड, सामग्री रिपोर्ट और अपील तथा रेफ़रल लेखांकन। वे आपसे नहीं, अनाम पहचानकर्ता से जुड़े रहते हैं।","b058":"खाता हटाकर दोबारा पंजीकरण से निःशुल्क साइन-अप क्रेडिट फिर पाने से रोकने के लिए, हटाने के बाद ईमेल का एकतरफ़ा हैश रखते हैं। वैध हित के आधार पर केवल धोखाधड़ी रोकने के लिए रखते हैं और किसी अन्य काम में नहीं लगाते। जहाँ आपने पोस्ट किया था उन नेटवर्कों पर कुछ पोस्ट या हटाया नहीं जाता: प्रत्येक नेटवर्क की अपनी सेटिंग में Veyrnox.ai की पहुँच रद्द करें।","b059":"साझाकरण","b060":"डेटा केवल सेवा चलाने हेतु आवश्यक कंपनियों से साझा करते हैं: प्रमाणीकरण और डेटाबेस होस्टिंग, एज होस्टिंग और स्टोरेज, सहमत वैकल्पिक विश्लेषण और निदान के लिए PostHog, AI मॉडल प्रदाता और उन तक अनुरोध पहुँचाने वाला मॉडल गेटवे, वेब खोज चालू होने पर खोज प्रदाता (हमारी खोज के लिए Exa या Parallel), खाते के ईमेल के लिए Resend और क्रेडिट पैक खरीद के लिए Stripe, Inc.। Stripe, Inc. Merchant of Record के रूप में की गई खरीद का स्वतंत्र नियंत्रक है। Publish पोस्ट निर्धारित करने पर उसका मीडिया और कैप्शन चुने सामाजिक नेटवर्कों को भेजते हैं। केवल फ़ाइल अपलोड करने से वह सामाजिक नेटवर्क पर नहीं जाती। हम व्यक्तिगत डेटा नहीं बेचते। Sentry ऊपर वर्णित आवश्यक सर्वर त्रुटि रिपोर्ट संसाधित करता है।","b072":"हम आवश्यक सर्वर-साइड त्रुटि रिपोर्टिंग के लिए Sentry का भी उपयोग करते हैं, जो वैकल्पिक विश्लेषिकी की आपकी पसंद से स्वतंत्र है। खराबियों का निदान करने और सेवा की सुरक्षा के लिए रिपोर्ट में त्रुटि प्रकार, कोड स्थान और साफ़ किए गए रूट पथ शामिल होते हैं। रिपोर्ट को प्रॉम्प्ट, चैट टेक्स्ट, मीडिया, पासवर्ड, भुगतान विवरण, अनुरोध बॉडी, हेडर, कुकी और हस्ताक्षरित लिंक टोकन को बाहर रखने के लिए कॉन्फ़िगर किया गया है। यह ब्राउज़र विश्लेषिकी या सत्र रीप्ले नहीं है।","b061":"आपके अधिकार","b063":"GDPR और डेटा अधिकार","b062":"आप डेटा देख, सुधार, निर्यात या हटा सकते हैं तथा कुछ संसाधन पर आपत्ति या प्रतिबंध लगा सकते हैं। प्रक्रिया के लिए {inline1} देखें। UK Information Commissioner’s Office या स्थानीय पर्यवेक्षी प्राधिकरण में शिकायत भी कर सकते हैं।","b064":"कुकी","b065":"लॉगिन, प्राथमिकताएँ और गोपनीयता विकल्प याद रखने तथा सेवा चलाने के लिए कड़ाई से आवश्यक कुकी और स्थानीय स्टोरेज उपयोग करते हैं। मित्र का रेफ़रल लिंक खोलने पर उसका कोड ब्राउज़र के स्थानीय स्टोरेज में अधिकतम तीन दिन रखते हैं ताकि पंजीकरण के समय खाते से जोड़ा जा सके, फिर हटा देते हैं। PostHog विश्लेषण स्टोरेज डिफ़ॉल्ट रूप से बंद है और केवल विश्लेषण या विश्लेषण और रीप्ले चुनने पर ही शुरू होता है। गोपनीयता विकल्प बटन से कभी भी चुनाव बदल या वापस ले सकते हैं। विज्ञापन ट्रैकर उपयोग नहीं करते।","b066":"रेफ़रल","b067":"किसी के रेफ़रल लिंक से जुड़ने पर हम दर्ज करते हैं कि किस खाते ने आपके खाते को रेफ़र किया। वह व्यक्ति लिंक से जुड़े मित्रों की संख्या देख सकता है लेकिन आपकी पहचान कभी नहीं बताई जाती। Credit Pack खरीदने पर उसे शर्तों के अनुसार क्रेडिट मिल सकते हैं; खरीद की धनवापसी या विवाद पर पुरस्कार वापस होता है।","b068":"बच्चे","b069":"सेवा 18 वर्ष से कम आयु वालों के लिए नहीं है।","b070":"परिवर्तन","b071":"महत्वपूर्ण बदलाव यहाँ प्रकाशित करेंगे और पृष्ठ के शीर्ष पर तारीख लिखेंगे।"},"refund":{"title":"धनवापसी नीति","description":"क्रेडिट कब आपके शेष में वापस आते हैं: विफल जनरेशन पर स्वचालित वापसी और खरीदे गए क्रेडिट का व्यवहार।","b001":"यह पृष्ठ जनरेशन, Credit Packs, Credit Subscriptions, Veyrnox.ai Publish Plan और Cinema Pass की धनवापसी समझाता है।","b002":"विफल जनरेशन — स्वचालित","b003":"प्रत्येक जनरेशन पुष्टि से पहले अपनी क्रेडिट लागत दिखाता है। प्रस्तुत करने पर क्रेडिट काटे जाते हैं। यदि मॉडल प्रदाता कार्य अस्वीकार करता है या परिणाम नहीं देता, तो पूरी कटौती स्वचालित रूप से आपके शेष में लौटती है, सामान्यतः कुछ सेकंड में। आपको हमसे संपर्क करने की आवश्यकता नहीं है। वापसी आपके लेजर में अलग प्रविष्टि के रूप में दिखाई देती है।","b004":"पूर्ण जनरेशन","b005":"जनरेशन पूरा होने और आउटपुट मिलने के बाद क्रेडिट खर्च हो चुके होते हैं। पूर्ण जनरेशन के क्रेडिट वापस नहीं किए जा सकते क्योंकि अंतर्निहित मॉडल प्रदाता हमसे गणना का शुल्क पहले ही ले चुका होता है।","b006":"निःशुल्क क्रेडिट","b007":"साइन-अप पर मिलने वाले 10 क्रेडिट का कोई नकद मूल्य नहीं है, वे धन के रूप में वापस नहीं किए जा सकते और उपयोग न होने पर दिए जाने के 90 दिन बाद समाप्त हो जाते हैं। खरीदे गए क्रेडिट कभी समाप्त नहीं होते।","b008":"खरीदे गए क्रेडिट","b009":"खरीद के 14 दिनों के भीतर क्रेडिट पैक की पूरी धनवापसी माँग सकते हैं, बशर्ते उस खरीद के बाद आपने कुछ भी जनरेट न किया हो। खरीद के बाद जनरेट करते ही उस खरीद की धनवापसी उपलब्ध नहीं रहती। धनवापसी मूल भुगतान विधि पर होती है और उस पैक के क्रेडिट आपके शेष से हटा दिए जाते हैं।","b010":"यदि आप UK या EU के उपभोक्ता हैं, तो इससे आपके वैधानिक रद्दीकरण अधिकार सीमित नहीं होते।","b011":"यदि आप किसी के रेफ़रल लिंक से जुड़े थे, तो पहले क्रेडिट पैक की धनवापसी उस खरीद से उन्हें मिले रेफ़रल पुरस्कार को भी वापस लेती है। इससे आपकी धनवापसी नहीं बदलती।","b012":"क्रेडिट सदस्यताएँ","b014":"क्रेडिट और बिलिंग","b013":"आप {inline1} से किसी भी समय नवीनीकरण रोक सकते हैं। आपके मौजूदा सदस्यता क्रेडिट केवल भुगतान किए गए चक्र के अंत तक उपलब्ध रहते हैं; वे आगे नहीं जुड़ते।","b015":"प्रारंभिक सदस्यता भुगतान के 14 दिनों के भीतर, यदि उस चक्र का कोई सदस्यता क्रेडिट उपयोग नहीं हुआ है, तो तत्काल रद्दीकरण और पूरी धनवापसी माँग सकते हैं। मूल भुगतान विधि पर धनवापसी भेजने से पहले उस चक्र के क्रेडिट हटा दिए जाते हैं।","b016":"यदि कोई सदस्यता क्रेडिट उपयोग किया जा चुका है या प्रारंभिक 14 दिन की अवधि समाप्त हो गई है, तो तत्काल धनवापसी का विकल्प उपलब्ध नहीं है। आप फिर भी अगला नवीनीकरण रोक सकते हैं।","b017":"लंबित या अस्वीकृत धनवापसी को पूर्ण नहीं बताया जाता। बिलिंग स्क्रीन सुधार योग्य अनुरोध को फिर से आज़माने या संचालक की समीक्षा आवश्यक होने पर सहायता से संपर्क करने देती है।","b018":"Veyrnox.ai Publish Plan","b019":"आप Publish Plan पृष्ठ या उसके Stripe बिलिंग पोर्टल से साप्ताहिक, मासिक या वार्षिक नवीनीकरण रोक सकते हैं। Plan वर्तमान भुगतान अवधि के अंत तक जारी रहता है।","b020":"धनवापसी के अनुरोध के लिए खाते के ईमेल और भुगतान संदर्भ के साथ सहायता से संपर्क करें। आपके वैधानिक अधिकार प्रभावित नहीं होते।","b021":"Cinema Pass","b022":"आप Cinema Pass पृष्ठ या उसके Stripe बिलिंग पोर्टल से रद्द कर सकते हैं। प्रारंभिक विचार-अवधि के बाद रद्दीकरण नवीनीकरण रोकता है और Pass वर्तमान भुगतान अवधि के अंत तक जारी रहता है।","b023":"पहले शुल्क के 14 दिनों के भीतर रद्द करने पर Pass तत्काल समाप्त हो जाता है और हम उस भुगतान अवधि के अप्रयुक्त हिस्से की राशि मूल भुगतान विधि पर लौटाते हैं।","b024":"Pass के चालान की धनवापसी उस Pass को समाप्त करती है। भुगतान विवाद भी Pass समाप्त करता है और विवाद की समीक्षा के दौरान खाता रोक सकता है।","b025":"रद्द कैसे करें","b027":"{email}","b026":"अपने खाते में सदस्यता या Pass का स्वयं-सेवा रद्दीकरण नियंत्रण उपयोग करें। आप खाते का ईमेल, रद्द किया जाने वाला उत्पाद और स्पष्ट रद्दीकरण अनुरोध सहित {inline1} पर ईमेल भी कर सकते हैं। कार्ड का विवरण न भेजें। हम परिणाम की पुष्टि ईमेल से करेंगे।","b028":"दोहरा शुल्क","b030":"{email}","b029":"प्रस्तुतियाँ पुनरावृत्ति पर समान प्रभाव वाली हैं: एक ही अनुरोध पर कभी दो बार कटौती नहीं होती। यदि आपको लगता है कि दोहरा शुल्क लगा है, तो कार्य संदर्भ {inline1} पर भेजें और हम लेजर जाँचेंगे।","b031":"दुरुपयोग","b032":"निःशुल्क क्रेडिट अनुदान या सेवा के दुरुपयोग का संकेत देने वाले धनवापसी अनुरोध अस्वीकार किए जा सकते हैं।"},"aup":{"title":"स्वीकार्य उपयोग नीति","description":"यौन सामग्री, मैलवेयर, प्रतिरूपण और सहमति संबंधी नियमों सहित, Veyrnox.ai का उपयोग किन चीज़ों को बनाने या प्रकाशित करने के लिए किया जा सकता है और किनके लिए नहीं।","b002":"शर्तें","b003":"Cinema सामग्री नीति","b001":"Veyrnox.ai टेक्स्ट प्रॉम्प्ट और अपलोड की गई फ़ाइलों को चित्र, वीडियो, वाणी और संगीत में बदलता है तथा अनुमोदित रचनाकारों को Social Cinema में कृतियाँ प्रस्तुत करने देता है। ये नियम प्रत्येक प्रॉम्प्ट, अपलोड, आउटपुट और प्रकाशन पर लागू होते हैं और {inline1} का हिस्सा हैं। Social Cinema में प्रस्तुतियाँ {inline2} का भी पालन करती हैं।","b004":"आपके पास अपलोड की जाने वाली सामग्री के अधिकार होने चाहिए","b005":"फ़ोटो, वीडियो या आवाज़ की रिकॉर्डिंग अपलोड करने से पहले, आपको उसका स्वामी होना चाहिए या उसमें पहचाने जा सकने वाले प्रत्येक व्यक्ति की अनुमति होनी चाहिए। जब किसी जनरेशन में अपलोड का उपयोग होता है, तो हम आपसे इसकी पुष्टि माँगते हैं और उस कार्य के साथ पुष्टि दर्ज करते हैं। झूठी पुष्टि इन शर्तों का उल्लंघन है।","b006":"निषिद्ध","b008":"यौन सामग्री।","b007":"{inline1} पोर्नोग्राफ़ी, स्पष्ट यौन सामग्री, यौन हिंसा, फ़ेटिश सामग्री या उत्तेजना पैदा करने के उद्देश्य से नग्नता, चाहे वास्तविक, काल्पनिक, एनिमेटेड या AI-जनित हो।","b010":"नाबालिगों से संबंधित कोई भी सामग्री।","b009":"{inline1} 18 वर्ष से कम आयु के किसी वास्तविक या जनित व्यक्ति का यौनकृत, शोषणकारी या दुर्व्यवहारपूर्ण चित्रण नहीं। इसमें वयस्क बताकर प्रस्तुत किए गए बालसदृश पात्र भी शामिल हैं। हम संदिग्ध बाल यौन शोषण सामग्री की सूचना दे सकते हैं और खाता बंद कर सकते हैं।","b012":"प्रतिरूपण और डीपफ़ेक।","b011":"{inline1} सार्वजनिक व्यक्तियों सहित किसी वास्तविक व्यक्ति के चेहरे, शरीर या आवाज़ का उपयोग करके उसे कुछ ऐसा कहते या करते दिखाना जो उसने नहीं कहा या किया। हम चेहरा बदलने या आवाज़ की क्लोनिंग के उपकरण नहीं देते, और हमारे उपलब्ध उपकरणों से भी ऐसा परिणाम प्राप्त करना निषिद्ध है।","b014":"बिना सहमति की अंतरंग छवियाँ","b013":"{inline1} किसी भी व्यक्ति की, तथा किसी वास्तविक, पहचान योग्य व्यक्ति का कोई भी यौनकृत चित्रण।","b016":"धोखा।","b015":"{inline1} AI आउटपुट को वास्तविक घटना की प्रामाणिक फ़ोटो या रिकॉर्डिंग के रूप में पेश करना, झूठी ख़बरें, नकली सबूत, जाली पहचान दस्तावेज़ या चुनाव संबंधी दुष्प्रचार।","b018":"उत्पीड़न और घृणा।","b017":"{inline1} किसी व्यक्ति या समूह को धमकाने, डराने या अपमानित करने वाली अथवा हिंसा या घृणास्पद विचारधारा को बढ़ावा देने वाली सामग्री।","b020":"अवैध गतिविधि","b019":"{inline1} जो UK के कानून या आपके स्थान के कानून के तहत अवैध हो, जिसमें किसी अन्य के कॉपीराइट या ट्रेडमार्क का उल्लंघन शामिल है।","b022":"मैलवेयर और असुरक्षित फ़ाइलें।","b021":"{inline1} मैलवेयर, निष्पादन योग्य कोड, मैक्रो, स्क्रिप्ट, छिपाए गए फ़ाइल प्रकार, डिकोडर की कमज़ोरियों का दुरुपयोग, दुर्भावनापूर्ण लिंक या किसी अन्य व्यक्ति अथवा सेवा की सुरक्षा भंग करने का कोई प्रयास।","b024":"प्लेटफ़ॉर्म का दुर्भावनापूर्ण उपयोग।","b023":"{inline1} मॉडल की सीधी पहुँच दोबारा बेचना, हमारी अनुरोध-दर सीमाओं या क्रेडिट लेखांकन को दरकिनार करना, स्क्रैपिंग करना या हमारे प्रदाताओं के सिस्टम की जाँच-पड़ताल करना।","b025":"AI आउटपुट का लेबल लगाना","b026":"यह सेवा जो कुछ भी बनाती है वह AI-जनित होता है। जहाँ वास्तविक फ़ुटेज की अपेक्षा हो वहाँ इसे प्रकाशित करने पर बताएँ कि यह AI-जनित है। AI Act के अंतर्गत EU सहित कुछ अधिकार-क्षेत्रों में यह प्रकटीकरण आवश्यक है।","b027":"हम इन नियमों को कैसे लागू करते हैं","b028":"हम प्रदाताओं के फ़िल्टर तथा अपनी स्वचालित और मानवीय समीक्षा का उपयोग करते हैं। सामग्री, बाल सुरक्षा और मैलवेयर की जाँच के दौरान अपलोड अलग रखे जा सकते हैं। आवश्यक जाँच अनुपस्थित, अनुपलब्ध या अनिर्णीत होने पर उसे उत्तीर्ण नहीं माना जाता। उल्लंघन मिलने पर हम जनरेशन या प्रकाशन अस्वीकार कर सकते हैं, सामग्री हटा सकते हैं, खाता निलंबित या बंद कर सकते हैं तथा कानून द्वारा आवश्यक रिकॉर्ड रख सकते हैं। इस नीति के उल्लंघन के कारण बंद किए गए खाते से जुड़े क्रेडिट वापस नहीं किए जाते।","b029":"रिपोर्ट करना","b031":"{email}","b030":"किसी सामग्री या खाते की रिपोर्ट करने के लिए लिंक या कार्य संदर्भ सहित {inline1} पर ईमेल करें। हम बिना सहमति दर्शाए गए वास्तविक व्यक्ति की रिपोर्टों का पहले उत्तर देते हैं।","b032":"परिवर्तन","b033":"सेवा में बदलाव के साथ हम इस नीति को अद्यतन करते हैं। पृष्ठ के शीर्ष पर दी गई तारीख लागू संस्करण को दर्शाती है।"},"cinema-content":{"title":"Cinema सामग्री नीति","description":"Veyrnox Social Cinema पर प्रकाशन के लिए सामग्री, आयु-वर्गीकरण और फ़ाइल-सुरक्षा के नियम।","b002":"शर्तें","b003":"स्वीकार्य उपयोग नीति","b001":"यह नीति Social Cinema को भेजे गए प्रत्येक शीर्षक, एपिसोड, पोस्टर, उपशीर्षक, ऑडियो ट्रैक, विवरण और अन्य फ़ाइल पर लागू होती है। यह हमारी {inline1} और {inline2} का हिस्सा है।","b004":"वह सामग्री जिसकी अनुमति नहीं है","b006":"यौन सामग्री:","b005":"{inline1} अश्लील साहित्य, स्पष्ट यौन क्रियाएँ, उत्तेजना के उद्देश्य वाली नग्नता, फ़ेटिश सामग्री, यौन हिंसा या यौन शोषण।","b008":"बच्चे:","b007":"{inline1} 18 वर्ष से कम आयु के व्यक्ति का कोई भी यौन, शोषणकारी या अपमानजनक चित्रण, चाहे वास्तविक, काल्पनिक, एनिमेटेड या AI-जनित हो। दिखने वाली आयु महत्वपूर्ण है; किसी पात्र को वयस्क बताने से बच्चे जैसा चित्रण स्वीकार्य नहीं हो जाता।","b010":"अंतरंग छवियाँ:","b009":"{inline1} बिना सहमति की अंतरंग छवियाँ, यौन डीपफ़ेक या किसी पहचाने जा सकने वाले वास्तविक व्यक्ति का यौन चित्रण।","b012":"गंभीर हानि:","b011":"{inline1} आतंकवाद, घृणा, आत्महत्या, आत्म-हानि, खान-पान संबंधी विकारों, खतरनाक कृत्यों या गंभीर अपराध को बढ़ावा देने वाली सामग्री; विश्वसनीय धमकियाँ; या तुष्टि के लिए प्रस्तुत वीभत्स क्रूरता।","b014":"धोखा और दुर्व्यवहार:","b013":"{inline1} प्रतिरूपण, ठगी, नकली साक्ष्य, दुर्भावनापूर्ण लिंक, निजता का उल्लंघन, उत्पीड़न या किसी अन्य व्यक्ति के अधिकारों का उल्लंघन करने वाली सामग्री।","b016":"असुरक्षित फ़ाइलें:","b015":"{inline1} मैलवेयर, निष्पादन योग्य कोड, मैक्रो, स्क्रिप्ट, छद्म फ़ाइल प्रकार, डिकोडर की कमजोरी का लाभ उठाने के उद्देश्य वाला दूषित मीडिया, या दर्शक अथवा सेवा की सुरक्षा भंग करने वाले लिंक।","b017":"Veyrnox दर्शक लेबल","b018":"निर्माताओं को एक लेबल चुनना और प्रत्येक लागू सामग्री चेतावनी घोषित करना आवश्यक है। ये Veyrnox के मार्गदर्शक लेबल हैं, आधिकारिक BBFC वर्गीकरण या BBFC प्रतीक नहीं।","b020":"सभी आयु:","b019":"{inline1} सामान्य दर्शकों के लिए उपयुक्त हल्की, आश्वस्त करने वाली सामग्री।","b022":"PG:","b021":"{inline1} कुछ दृश्य छोटे या संवेदनशील बच्चों के लिए अनुपयुक्त हो सकते हैं; अभिभावकीय मार्गदर्शन की सलाह दी जाती है।","b024":"12+:","b023":"{inline1} मध्यम स्तर का खतरा, हिंसा, भाषा या परिपक्व विषय।","b026":"15+:","b025":"{inline1} तीखी भाषा, हिंसा, भय, नशीले पदार्थों के संदर्भ या परिपक्व विषय।","b028":"18+:","b027":"{inline1} तीव्र वयस्क विषय या इस नीति की सीमाओं के भीतर की हिंसा। 18+ लेबल कभी भी प्रतिबंधित यौन सामग्री की अनुमति नहीं देता।","b029":"प्रकाशन से पहले समीक्षा","b030":"स्वचालित प्रणालियों द्वारा मेटाडेटा, छवियों, नमूना वीडियो फ़्रेमों, वाणी या उपशीर्षकों, फ़ाइल संरचना और मैलवेयर संकेतों की जाँच के दौरान प्रस्तुतियाँ निजी रहती हैं। प्रस्तुति किसी प्रशिक्षित समीक्षक को भेजी जा सकती है। स्वचालित जाँच गलत हो सकती है, इसलिए अनिश्चित मामलों में वह मानवीय निर्णयों की सहायता करती है, उनका स्थान नहीं लेती।","b031":"हम सामग्री अस्वीकार, सीमित, निलंबित या हटा सकते हैं, ऑडिट रिकॉर्ड रख सकते हैं और गंभीर या बार-बार उल्लंघन पर खाते सीमित या बंद कर सकते हैं। कानूनन आवश्यक होने पर संदिग्ध अवैध सामग्री की रिपोर्ट कर सकते हैं। आवश्यक जाँच अनुपस्थित, अनुपलब्ध या अनसुलझी होने पर हम शीर्षक प्रकाशित नहीं करते।","b032":"रिपोर्ट और अपील","b034":"{email}","b033":"किसी शीर्षक की रिपोर्ट करने या निर्णय की समीक्षा माँगने के लिए {inline1} पर लिखें। शीर्षक का लिंक और संक्षिप्त स्पष्टीकरण दें। अवैध छवियाँ या संदिग्ध मैलवेयर ईमेल न करें।"},"gdpr":{"title":"GDPR और डेटा अधिकार","description":"Veyrnox.ai के पास मौजूद आपके डेटा पर पहुँच, निर्यात, सुधार और मिटाने के अधिकारों का प्रयोग कैसे करें।","b001":"{name} UK GDPR के अंतर्गत और EU निवासियों के लिए EU GDPR के अंतर्गत व्यक्तिगत डेटा संसाधित करती है। यह पृष्ठ आपके अधिकारों के प्रयोग की विधि बताता है।","b002":"आपके अधिकार","b004":"पहुँच","b003":"{inline1} — हमारे पास मौजूद आपके व्यक्तिगत डेटा की एक प्रति।","b006":"सुधार","b005":"{inline1} — गलत डेटा का सुधार।","b008":"मिटाना","b009":"क्या मिटाया जाता है और क्या रहता है","b007":"{inline1} — आपका खाता और व्यक्तिगत डेटा मिटाना, उन अभिलेखों को छोड़कर जिन्हें कानूनन रखना आवश्यक है (जैसे कर के लिए ज़रूरी लेजर प्रविष्टियाँ)। आप खाता और सुरक्षा से स्वयं अपना खाता मिटा सकते हैं; देखें {inline2}।","b011":"पोर्टेबिलिटी","b010":"{inline1} — आपके खाते का डेटा, जनरेशन मेटाडेटा और चैट वार्तालाप मशीन-पठनीय प्रारूप में।","b013":"प्रतिबंध और आपत्ति","b012":"{inline1} — वैध हितों पर आधारित प्रसंस्करण के लिए।","b015":"सहमति वापस लेना","b014":"{inline1} — जहाँ प्रसंस्करण सहमति पर आधारित हो।","b016":"अनुरोध कैसे करें","b018":"{privacyEmail}","b017":"अपने खाते के ईमेल पते से {inline1} पर लिखें। हम एक माह के भीतर उत्तर देते हैं; जटिल अनुरोधों में अधिकतम दो अतिरिक्त माह लग सकते हैं और ऐसा होने पर हम आपको बताएँगे। स्पष्ट रूप से निराधार या अत्यधिक न होने पर अनुरोध निःशुल्क हैं।","b019":"डेटा कहाँ संसाधित होता है","b020":"हमारा डेटाबेस, जिसमें खाते का डेटा, क्रेडिट लेजर, जनरेशन मेटाडेटा और चैट वार्तालाप हैं, यूरोपीय संघ (फ़्रैंकफ़र्ट, जर्मनी) में होस्ट किया गया है। जनरेट किया गया मीडिया यूरोपीय संघ में EU क्षेत्राधिकार प्रतिबंध वाले Cloudflare R2 में संग्रहीत है। मॉडल प्रदाता जनरेशन के दौरान आपके प्रॉम्प्ट और संदर्भ फ़ाइलों को UK या EEA के बाहर संसाधित कर सकते हैं। UK या EEA के बाहर प्रत्येक हस्तांतरण के लिए हम संबंधित प्रोसेसर के साथ UK International Data Transfer Agreement या EU Standard Contractual Clauses पर निर्भर करते हैं।","b021":"स्वचालित निर्णय","b022":"हम केवल स्वचालित साधनों से आपके संबंध में कानूनी या समान रूप से महत्वपूर्ण प्रभाव वाले निर्णय नहीं लेते। सामग्री-सुरक्षा फ़िल्टर जनरेशन रोक सकते हैं; आप हमसे रोक की समीक्षा माँग सकते हैं।","b023":"सामग्री की उत्पत्ति","b024":"वर्तमान में हम जनरेट की गई फ़ाइलों में सामग्री प्रमाणपत्र या उत्पत्ति मेटाडेटा नहीं जोड़ते, इसलिए हम आउटपुट के भीतर आपका कोई व्यक्तिगत डेटा शामिल नहीं करते। मॉडल प्रदाता अपना वॉटरमार्क या पहचानकर्ता जोड़ सकता है; यह हमारे नियंत्रण के बाहर है और हम इसके ऊपर कोई अन्य नहीं जोड़ते।","b025":"शिकायतें","b026":"UK: Information Commissioner’s Office, ico.org.uk। EU: आपका स्थानीय पर्यवेक्षी प्राधिकरण। हम पहले आपकी चिंता का समाधान करने का अवसर चाहेंगे।","b027":"नियंत्रक का विवरण","b028":"{name} · कंपनी संख्या {companyNo} · {office}"}},"chrome":{"translation":"सुविधा के लिए अनुवाद","notice":"यह मशीन अनुवाद केवल सुविधा के लिए दिया गया है। किसी वकील ने इसकी समीक्षा नहीं की है। किसी भी अंतर की स्थिति में अंग्रेज़ी पाठ प्रभावी होगा।","english":"अंग्रेज़ी पाठ पढ़ें","agree":"मैं ऊपर दिए गए अंग्रेज़ी पाठ से सहमत हूँ।","company":"{name}, जो {trading} के नाम से कारोबार करती है। कंपनी संख्या {companyNo}। अंतिम अद्यतन: {updated}।","nav":"कानूनी जानकारी","terms":"शर्तें","privacy":"गोपनीयता","refund":"धनवापसी","aup":"स्वीकार्य उपयोग","cinema-content":"Cinema सामग्री","gdpr":"GDPR और डेटा अधिकार","home":"Veyrnox.ai मुख्य पृष्ठ"},"jurisdiction":"इंग्लैंड और वेल्स","tag":"hi"};
